// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ILayerZeroEndpoint} from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroEndpoint.sol";
import {ILayerZeroReceiver} from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroReceiver.sol";

contract MidPayClient is Ownable, ILayerZeroReceiver {
    event LzCall(
        uint16 srcChainId,
        bytes srcAddress,
        uint64 nonce,
        bytes payload
    );
    event HashAlreadyProcessed();
    event InvalidEndpoint();
    event LookupNotTrusted();

    mapping(uint16 => bytes) public trustedRemoteLookup;
    mapping(bytes32 => bool) public processed;

    ILayerZeroEndpoint public layerZeroEndpoint;
    IERC20 public usdc;
    address public coreAddress;
    uint16 public coreChainId;

    constructor(
        address _usdc,
        address _layerZeroEndpoint,
        address _coreAddress,
        uint16 _coreChainId
    ) Ownable(msg.sender) {
        usdc = IERC20(_usdc);
        layerZeroEndpoint = ILayerZeroEndpoint(_layerZeroEndpoint);
        coreAddress = _coreAddress;
        coreChainId = _coreChainId;
    }

    function deposit(uint256 amount) external {
        usdc.transferFrom(msg.sender, address(this), amount);

        _send(amount, true);
    }

    function withdraw(uint256 amount) external {
        _send(amount, false);
    }

    function _send(uint256 amount, bool isDeposit) internal {
        bytes memory payload = abi.encode(msg.sender, amount, isDeposit);
        bytes memory remoteAndLocalAddresses = abi.encodePacked(
            coreAddress,
            address(this)
        );

        bytes memory adapterParams = isDeposit
            ? bytes("")
            : abi.encodePacked(uint16(1), uint256(500000));
        (uint256 nativeFee, ) = layerZeroEndpoint.estimateFees(
            coreChainId,
            coreAddress,
            payload,
            false,
            adapterParams
        );
        layerZeroEndpoint.send{value: nativeFee}(
            coreChainId,
            remoteAndLocalAddresses,
            payload,
            payable(address(this)),
            address(0x0),
            adapterParams
        );
    }

    /// @notice This function should not revert, as it should not be blocking the future transfers.
    function lzReceive(
        uint16 _srcChainId,
        bytes memory _srcAddress,
        uint64 _nonce,
        bytes memory _payload
    ) external override {
        emit LzCall(_srcChainId, _srcAddress, _nonce, _payload);
        bytes32 hash = keccak256(
            abi.encodePacked(_srcChainId, _srcAddress, _nonce, _payload)
        );
        if (processed[hash]) {
            emit HashAlreadyProcessed();
            return;
        }
        processed[hash] = true;

        if (msg.sender != address(layerZeroEndpoint)) {
            emit InvalidEndpoint();
            return;
        }

        if (
            keccak256(_srcAddress) !=
            keccak256(trustedRemoteLookup[_srcChainId])
        ) {
            emit LookupNotTrusted();
            return;
        }

        (address to, uint256 amount) = abi.decode(_payload, (address, uint256));

        usdc.transfer(to, amount);
    }

    function setTrustedRemoteLookup(
        uint16 _srcChainId,
        bytes memory _srcAddress
    ) external onlyOwner {
        trustedRemoteLookup[_srcChainId] = _srcAddress;
    }

    function setLayerZeroEndpoint(
        address _layerZeroEndpoint
    ) external onlyOwner {
        layerZeroEndpoint = ILayerZeroEndpoint(_layerZeroEndpoint);
    }

    function setCoreAddress(address _coreAddress) external onlyOwner {
        coreAddress = _coreAddress;
    }

    function setCoreChainId(uint16 _coreChainId) external onlyOwner {
        coreChainId = _coreChainId;
    }

    function setUsdc(address _usdc) external onlyOwner {
        usdc = IERC20(_usdc);
    }

    function withdrawEth() external onlyOwner {
        (bool success, ) = payable(msg.sender).call{
            value: address(this).balance
        }("");
        require(success, "MidPay: Withdraw failed");
    }

    receive() external payable {}
}

contracts/MidPayCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ILayerZeroEndpoint} from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroEndpoint.sol";
import {ILayerZeroReceiver} from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroReceiver.sol";
import {IExternalRouter} from "./interfaces/IExternalRouter.sol";

contract MidPayCore is Ownable, ILayerZeroReceiver {
    event LzCall(
        uint16 srcChainId,
        bytes srcAddress,
        uint64 nonce,
        bytes payload
    );
    event HashAlreadyProcessed();
    event InvalidEndpoint();
    event LookupNotTrusted();
    event Deposited(address user, uint256 amount);
    event Withdrawn(address user, uint256 amount);
    event NotEnoughBalance();

    mapping(address => uint256) public balances;
    mapping(uint16 => bytes) public trustedRemoteLookup;
    mapping(bytes32 => bool) public processed;

    IExternalRouter public externalRouter;
    ILayerZeroEndpoint public layerZeroEndpoint;
    IERC20 public usdc;

    constructor(address _usdc, address _layerZeroEndpoint) 
    Ownable(msg.sender)
    {
        usdc = IERC20(_usdc);
        layerZeroEndpoint = ILayerZeroEndpoint(_layerZeroEndpoint);
    }

    function deposit(uint256 amount) external {
        usdc.transferFrom(msg.sender, address(this), amount);
        balances[msg.sender] += amount;
    }

    function withdraw(uint256 amount) external {
        balances[msg.sender] -= amount;
        usdc.transfer(msg.sender, amount);
    }

    /// @notice This function should not revert, as it should not be blocking the future transfers.
    function lzReceive(uint16 _srcChainId, bytes memory _srcAddress, uint64 _nonce, bytes memory _payload)
        external
        override
    {
        emit LzCall(_srcChainId, _srcAddress, _nonce, _payload);
        bytes32 hash = keccak256(abi.encodePacked(_srcChainId, _srcAddress, _nonce, _payload));
        if (processed[hash]) {
            emit HashAlreadyProcessed();
            return;
        }
        processed[hash] = true;

        if (msg.sender != address(layerZeroEndpoint) && msg.sender != address(externalRouter)) {
            emit InvalidEndpoint();
            return;
        }

        if (keccak256(_srcAddress) != keccak256(trustedRemoteLookup[_srcChainId])) {
            emit LookupNotTrusted();
            return;
        }

        (address from, uint256 amount, bool isDeposit) = abi.decode(_payload, (address, uint256, bool));

        if (isDeposit) {
            balances[from] += amount;
            emit Deposited(from, amount);
            return;
        } else {
            if (balances[from] < amount) {
                emit NotEnoughBalance();
                return;
            }
            balances[from] -= amount;
            emit Withdrawn(from, balances[from]);
        }

        address fromAddress;
        assembly {
            fromAddress := mload(add(_srcAddress, 20))
        }

        bytes memory payload = abi.encode(from, amount);
        bytes memory remoteAndLocalAddresses = abi.encodePacked(fromAddress, address(this));

        if (msg.sender == address(externalRouter)) {
            externalRouter.send(
                _srcChainId, remoteAndLocalAddresses, payload, payable(address(this)), address(0x0), bytes("")
            );
            return;
        }

        (uint256 nativeFee,) = layerZeroEndpoint.estimateFees(_srcChainId, fromAddress, _payload, false, bytes(""));

        layerZeroEndpoint.send{value: nativeFee}(
            _srcChainId, remoteAndLocalAddresses, payload, payable(address(this)), address(0x0), bytes("")
        );
    }

    function setTrustedRemoteLookup(uint16 _srcChainId, bytes memory _srcAddress) external onlyOwner {
        trustedRemoteLookup[_srcChainId] = _srcAddress;
    }

    function setLayerZeroEndpoint(address _layerZeroEndpoint) external onlyOwner {
        layerZeroEndpoint = ILayerZeroEndpoint(_layerZeroEndpoint);
    }

    function setExternalRouter(address _externalRouter) external onlyOwner {
        externalRouter = IExternalRouter(_externalRouter);
    }

    function setUsdc(address _usdc) external onlyOwner {
        usdc = IERC20(_usdc);
    }

    function withdrawEth() external onlyOwner {
        (bool success,) = payable(msg.sender).call{value: address(this).balance}("");
        require(success, "MidPayCore: Withdraw failed");
    }

    receive() external payable {}
}

contracts/router/ExternalRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ILayerZeroEndpoint} from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroEndpoint.sol";
import {ILayerZeroReceiver} from "@layerzerolabs/solidity-examples/contracts/lzApp/interfaces/ILayerZeroReceiver.sol";
import {IExternalRouter} from "../interfaces/IExternalRouter.sol";

contract ExternalRouter is IExternalRouter, Ownable {
    struct Message {
        uint16 chainId;
        bytes addressCombination;
        bytes payload;
    }

    event MessageSent(Message message);

    Message[] public messageQueue;
    uint16 public currentChainId;
    mapping(bytes => uint64) public lastNonces;
    ILayerZeroReceiver public midPay;

    constructor(address _midPay, uint16 _currentChainId)
    Ownable(msg.sender)
     {
        midPay = ILayerZeroReceiver(_midPay);
        currentChainId = _currentChainId;
    }

    function send(
        uint16 _dstChainId,
        bytes calldata _destination,
        bytes calldata _payload,
        address payable,
        address,
        bytes calldata
    ) external override {
        require(
            msg.sender == address(midPay),
            "ExternalRouter: Only MidPay can call this function"
        );

        Message memory message = Message(_dstChainId, _destination, _payload);
        messageQueue.push(message);

        emit MessageSent(message);
    }

    function estimateFees(
        uint16,
        address,
        bytes calldata,
        bool,
        bytes calldata
    ) external pure returns (uint256, uint256) {
        return (0, 0);
    }

    function queueLength() external view returns (uint256) {
        return messageQueue.length;
    }

    function route(Message calldata message) external onlyOwner {
        midPay.lzReceive(
            message.chainId,
            message.addressCombination,
            ++lastNonces[message.addressCombination],
            message.payload
        );
    }
    
    function pop() external onlyOwner {
        require(messageQueue.length > 0, "ExternalRouter: No messages in queue");

        messageQueue.pop();
    }

    function setMidPay(address _midPay) external onlyOwner {
        midPay = ILayerZeroReceiver(_midPay);
    }

    function withdraw() external onlyOwner {
        (bool success,) = payable(msg.sender).call{value: address(this).balance}("");
        require(success, "ExternalRouter: Withdraw failed");
    }

    receive() external payable {}
}

contracts/util/FakeUSDC.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract FakeUSDC is ERC20, Ownable {
    mapping(address => bool) public minted;

    constructor() Ownable(msg.sender) ERC20("Fake USD Coin", "fUSDC") {}

    function mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function mintOnce(address to) external {
        require(!minted[to], "FakeUSDC: already minted");
        minted[to] = true;
        _mint(to, 100e18);
    }
}

